import json
from typing import List

class Solution:
    def minimumDifference(self, nums: List[int]) -> int:
        n = len(nums) // 2
        left, right = nums[:n], nums[n:]
        total = sum(nums)
        left_sums = [[] for _ in range(n + 1)]
        right_sums = [[] for _ in range(n + 1)]
        for mask in range(1 << n):
            count = mask.bit_count()
            ls = rs = 0
            for i in range(n):
                if mask & (1 << i):
                    ls += left[i]
                    rs += right[i]
            left_sums[count].append(ls)
            right_sums[count].append(rs)
        for sums in right_sums:
            sums.sort()
        import bisect
        ans = float("inf")
        for count in range(n + 1):
            candidates = right_sums[n - count]
            for ls in left_sums[count]:
                target = total / 2 - ls
                pos = bisect.bisect_left(candidates, target)
                for p in (pos - 1, pos):
                    if 0 <= p < len(candidates):
                        ans = min(ans, abs(total - 2 * (ls + candidates[p])))
        return int(ans)

