import java.io.*;
import java.util.*;

class Solution {
    public int minimumDifference(int[] nums) {
        int n = nums.length / 2;
        int[] left = Arrays.copyOfRange(nums, 0, n);
        int[] right = Arrays.copyOfRange(nums, n, 2 * n);
        long total = 0; for (int x : nums) total += x;
        List<Long>[] ls = new ArrayList[n + 1], rs = new ArrayList[n + 1];
        for (int i = 0; i <= n; i++) { ls[i] = new ArrayList<>(); rs[i] = new ArrayList<>(); }
        for (int mask = 0; mask < (1 << n); mask++) {
            int count = Integer.bitCount(mask); long a = 0, b = 0;
            for (int i = 0; i < n; i++) if ((mask & (1 << i)) != 0) { a += left[i]; b += right[i]; }
            ls[count].add(a); rs[count].add(b);
        }
        for (List<Long> list : rs) Collections.sort(list);
        long ans = Long.MAX_VALUE;
        for (int count = 0; count <= n; count++) {
            List<Long> candidates = rs[n - count];
            for (long a : ls[count]) {
                long target2 = total - 2 * a;
                int lo = 0, hi = candidates.size();
                while (lo < hi) { int mid = (lo + hi) >>> 1; if (2 * candidates.get(mid) < target2) lo = mid + 1; else hi = mid; }
                for (int p : new int[]{lo - 1, lo}) if (p >= 0 && p < candidates.size()) ans = Math.min(ans, Math.abs(total - 2 * (a + candidates.get(p))));
            }
        }
        return (int) ans;
    }
}

