#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int minimumDifference(vector<int>& nums) {
        int n = nums.size() / 2;
        vector<int> left(nums.begin(), nums.begin() + n), right(nums.begin() + n, nums.end());
        long long total = accumulate(nums.begin(), nums.end(), 0LL);
        vector<vector<long long>> ls(n + 1), rs(n + 1);
        for (int mask = 0; mask < (1 << n); ++mask) {
            int count = __builtin_popcount((unsigned)mask); long long a = 0, b = 0;
            for (int i = 0; i < n; ++i) if (mask & (1 << i)) { a += left[i]; b += right[i]; }
            ls[count].push_back(a); rs[count].push_back(b);
        }
        for (auto& v : rs) sort(v.begin(), v.end());
        long long ans = LLONG_MAX;
        for (int count = 0; count <= n; ++count) {
            auto& cand = rs[n - count];
            for (long long a : ls[count]) {
                long double target = (long double)total / 2 - a;
                auto it = lower_bound(cand.begin(), cand.end(), target);
                for (auto jt : {it == cand.begin() ? cand.end() : prev(it), it}) if (jt != cand.end()) ans = min(ans, llabs(total - 2 * (a + *jt)));
            }
        }
        return (int)ans;
    }
};

