function minimumDifference(nums) {
  const n = nums.length / 2;
  const left = nums.slice(0, n), right = nums.slice(n);
  const total = nums.reduce((a, b) => a + b, 0);
  const leftSums = Array.from({length: n + 1}, () => []);
  const rightSums = Array.from({length: n + 1}, () => []);
  for (let mask = 0; mask < (1 << n); mask++) {
    let count = 0, ls = 0, rs = 0;
    for (let i = 0; i < n; i++) if (mask & (1 << i)) { count++; ls += left[i]; rs += right[i]; }
    leftSums[count].push(ls); rightSums[count].push(rs);
  }
  for (const a of rightSums) a.sort((x, y) => x - y);
  function lowerBound(a, x) { let l = 0, r = a.length; while (l < r) { const m = (l + r) >> 1; if (a[m] < x) l = m + 1; else r = m; } return l; }
  let ans = Infinity;
  for (let count = 0; count <= n; count++) {
    const candidates = rightSums[n - count];
    for (const ls of leftSums[count]) {
      const pos = lowerBound(candidates, total / 2 - ls);
      for (const p of [pos - 1, pos]) if (p >= 0 && p < candidates.length) ans = Math.min(ans, Math.abs(total - 2 * (ls + candidates[p])));
    }
  }
  return ans;
}

