static int minimumDifference(int* nums, int len) {
    int n = len / 2, total = 0;
    for (int i = 0; i < len; ++i) total += nums[i];
    int count = 1 << n;
    long long** ls = malloc((n + 1) * sizeof(long long*));
    long long** rs = malloc((n + 1) * sizeof(long long*));
    int* sizes = calloc(n + 1, sizeof(int));
    for (int i = 0; i <= n; ++i) { ls[i] = malloc(count * sizeof(long long)); rs[i] = malloc(count * sizeof(long long)); }
    for (int mask = 0; mask < count; ++mask) {
        int c = __builtin_popcount((unsigned)mask); long long a = 0, b = 0;
        for (int i = 0; i < n; ++i) if (mask & (1 << i)) { a += nums[i]; b += nums[n + i]; }
        ls[c][sizes[c]] = a; rs[c][sizes[c]] = b; sizes[c]++;
    }
    for (int c = 0; c <= n; ++c) {
        int m = sizes[c];
        for (int i = 1; i < m; ++i) { long long key = rs[c][i]; int j = i - 1; while (j >= 0 && rs[c][j] > key) { rs[c][j+1] = rs[c][j]; --j; } rs[c][j+1] = key; }
    }
    long long ans = LLONG_MAX;
    for (int c = 0; c <= n; ++c) {
        int rc = n - c, m = sizes[rc];
        for (int i = 0; i < sizes[c]; ++i) {
            long long target2 = (long long)total - 2 * ls[c][i];
            int lo = 0, hi = m;
            while (lo < hi) { int mid = (lo + hi) / 2; if (2 * rs[rc][mid] < target2) lo = mid + 1; else hi = mid; }
            for (int p = lo - 1; p <= lo; ++p) if (p >= 0 && p < m) { long long d = llabs((long long)total - 2 * (ls[c][i] + rs[rc][p])); if (d < ans) ans = d; }
        }
    }
    for (int i = 0; i <= n; ++i) { free(ls[i]); free(rs[i]); } free(ls); free(rs); free(sizes);
    return (int)ans;
}

